  "implementation": "import sys

def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build edge list with canonical ordering and mutual reachability
    edges = []
    for u, v, d in distances:
        w = max(core_distance[u], core_distance[v], d)
        if u > v:
            u, v = v, u
        edges.append((w, u, v))

    # Sort by weight, then by first endpoint, then second
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    target_edges = len(nodes) - 1
    edge_count = 0

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            edge_count += 1
            if edge_count == target_edges:
                break

    if edge_count != target_edges:
        raise ValueError("Graph is disconnected; cannot form MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
